const { useState } = React;

function CourseForm() {
  const [form, setForm] = useState({ title: '', hours: '0', level: '입문', open: false });

  const change = (e) => {
    const { name, value, type, checked } = e.target;
    setForm({ ...form, [name]: type === 'checkbox' ? checked : value });
  };

  return (
    <div>
      <label className="field" htmlFor="title">제목</label>
      <input className="field__input" id="title" name="title" value={form.title} onChange={change} />

      <label className="field" htmlFor="hours">시간</label>
      <input className="field__input" id="hours" name="hours" type="number" value={form.hours} onChange={change} />

      <label className="field" htmlFor="level">난이도</label>
      <select className="field__input" id="level" name="level" value={form.level} onChange={change}>
        <option value="입문">입문</option>
        <option value="심화">심화</option>
      </select>

      <label className="field" htmlFor="open">
        <input id="open" name="open" type="checkbox" checked={form.open} onChange={change} /> 공개
      </label>

      <p className="preview">
        {form.title === '' ? '제목 없음' : form.title} · {form.hours}시간 · {form.level} · {form.open ? '공개' : '비공개'}
      </p>
    </div>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<CourseForm />);

